import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        long[] a = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) total += a[i] = next();
        // d = best (lock holder - other) over the suffix; taking an item flips the roles.
        long d = 0;
        for (int i = n - 1; i >= 0; i--) d = Math.abs(a[i] - d);
        System.out.println((total + d) / 2 + " " + (total - d) / 2);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	a := make([]int64, n)
	var total int64
	for i := range a {
		a[i] = next()
		total += a[i]
	}
	// d = best (lock holder - other) over the suffix; taking an item flips the roles.
	var d int64
	for i := n - 1; i >= 0; i-- {
		d = a[i] - d
		if d < 0 {
			d = -d
		}
	}
	fmt.Println((total+d)/2, (total-d)/2)
}
